const e="cloverdale-citrus-fair-got-talent",d=2025,i="Built from the 2025 rules and application (English and Spanish copies). The source prints no judging criteria, marks, ranks, complaints procedure or fee. The application's name, address and telephone fields are not copied. Dates, times and prizes are the 2025 edition's values and are the starting suggestion for the next edition.",a={Title:"Rules & Criteria",Subtitle:"Cloverdale's Got Talent at the Cloverdale Citrus Fair: solo and group acts in four age divisions, on {{ContestDate}}.",NoticeTitle:"Please Read Before Registering",Notice:"Applications are due in the fair office by {{ApplicationDeadline}}. The number of contestants is limited, so enter as early as possible.",Notes:["Optional rehearsal: {{RehearsalDay}}. Rehearsal is not mandatory.","Check in at the auditorium at {{CheckInTime}} on the day of the show."],Sections:[{Key:"general",Title:"General",Items:["The show is held on {{ContestDate}} at {{ContestVenue}}.","Each entry has a time limit of 4 (four) minutes.","Singing, Dance, Instrumental and All Other categories are judged separately, but the highest scores are used to decide the overall age division winners and the grand prize winners.","Contestants receive free admission to the fair on the Sunday of the show. Tickets are picked up in the fair office.","Same-day sound check or stage access may be available. Work with the Contest Chair to schedule it."]},{Key:"eligibility",Title:"Who can enter",Items:["There are four age divisions: Tiny (4-8), Junior (9-12), Teen (13-17) and Adult (18 and over).","Entries may be made by individuals or by groups.","If the ages of group participants fall in two or more divisions, the group enters the older division. For example, one 8-year-old and two 9-year-olds enter the Junior division.","Adults who serve only as accompanists, and do not perform, do not change the age division of the participants."]},{Key:"registration",Title:"How to enter",Items:["Fill in the Talent Show Application: name or names, address, city, zip, telephone, e-mail, age division, Individual or Group, type of entry, and title of the performance or music.","For a group entry, print the name of the group and the names of all performers on the back of the application.","Circle one type of entry: Singing, Dancing, Instrumental, Acrobatics, Comedy Routine, or Other with a short description.","Bring the application to the fair office, e-mail it to {{FairContact}}, or mail it to {{FairOffice}}.","The application is due in the fair office by {{ApplicationDeadline}}.","The number of contestants is limited, so enter as early as possible.","Bring your music (CD or similar) to the rehearsal.","Office hours are {{OfficeHours}}.","For more information, call or e-mail {{FairContact}}."]},{Key:"dates",Title:"Dates",Items:["The show is on {{ContestDate}} at {{ShowTime}}.","Applications are due by {{ApplicationDeadline}}.","The optional rehearsal is on {{RehearsalDay}}.","Contestants check in at the auditorium at {{CheckInTime}} on the day of the show."]},{Key:"venue",Title:"Venue",Items:["The show is held in {{ContestVenue}}."]},{Key:"prizes",Title:"Prizes",Items:["In each of the four age divisions, the first-place winner with the highest score receives {{DivisionPrize}} and a trophy.","Ribbons are awarded through third place.","One overall individual winner and one overall winning group each receive {{GrandPrize}} and a trophy."]},{Key:"other",Title:"Other",Items:[`The fair's printed theme for this edition is "The Good Ole Days: Remember When...".`,"The rules and application are printed in English and Spanish with the same content."]}],Documents:[{Title:"2025 Talent Show rules and application, English and Spanish (PDF)",Url:"https://cloverdalecitrusfair.org/wp-content/uploads/2025/01/2025-Talent-Show-Form-Bilingual.pdf"}]},t=[{ParticipantType:"Team",Source:"2025 rules and application (age note)",Sections:{About:null,TimeAndFormat:null,Rules:["Print the name of the group and the names of all performers on the back of the application.","If group members fall in two or more age divisions, the group enters the older division."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Print the name of the group and the names of all performers on the back of the application.
- If group members fall in two or more age divisions, the group enters the older division.`}],n=[],o=[{Title:"Instrumental",Source:"2025 rules and application (type of entry)",Sections:{About:null,TimeAndFormat:null,Rules:null,Allowed:["Acoustic instruments only."],NotAllowed:["No electric instruments at all."],Judging:null,Points:null,Notes:null},Markdown:`## Allowed
- Acoustic instruments only.

## Not allowed
- No electric instruments at all.`}],r=[],l=[{Key:"ContestDate",Kind:"date",Label:"Show date",Value:"2025-02-16",Source:"2025 rules and application"},{Key:"ShowTime",Kind:"time",Label:"Show start time",Value:"2:00 p.m.",Source:"2025 rules and application"},{Key:"CheckInTime",Kind:"time",Label:"Contestant check-in time",Value:"1:30 p.m.",Source:"2025 rules and application rule 7"},{Key:"ApplicationDeadline",Kind:"date",Label:"Applications due in the fair office",Value:"2025-02-12",Source:"2025 rules and application rule 1"},{Key:"RehearsalDay",Kind:"text",Label:"Optional rehearsal",Value:"Friday, 7 February 2025 at 6 p.m.",Source:"2025 rules and application rule 4"},{Key:"ContestVenue",Kind:"address",Label:"Show venue",Value:{Name:"Auditorium, Cloverdale Citrus Fair",Address:"1 Citrus Fair Drive",City:"Cloverdale, CA 95425",MapUrl:"",Directions:""},Source:"2025 rules and application"},{Key:"FairOffice",Kind:"address",Label:"Fair office (apply here)",Value:{Name:"Cloverdale Citrus Fair office",Address:"1 Citrus Fair Drive",City:"Cloverdale, CA 95425",MapUrl:"",Directions:""},Source:"2025 rules and application"},{Key:"OfficeHours",Kind:"text",Label:"Fair office hours",Value:"9 a.m. to 5 p.m. (closed for lunch 12 to 1 p.m.)",Source:"2025 rules and application"},{Key:"FairContact",Kind:"contact",Label:"Contact for information",Value:{Name:"Cloverdale Citrus Fair administration",Role:"Fair office",Phone:"(707) 894-3992",WhatsApp:"",Email:"administration@cloverdalecitrusfair.org"},Source:"2025 rules and application rule 8"},{Key:"DivisionPrize",Kind:"prize",Label:"First place prize per age division",Value:"a $25 cash award",Source:"2025 rules and application"},{Key:"GrandPrize",Kind:"prize",Label:"Grand prize (one individual and one group)",Value:"$100 cash",Source:"2025 rules and application"},{Key:"Announcements",Kind:"news",Label:"News printed in the rules",Value:[{Date:"2025-02-16",Title:"2025 fair theme",Text:"2025 Cloverdale Citrus Fair theme: The Good Ole Days: Remember When...",Url:""}],Source:"2025 rules and application"}],s=[{Claim:"Age divisions, entry types, time limit, prizes, dates, rules and how to apply are taken from the organiser's 2025 rules and application.",SourceType:"Primary - the event's own rules document",Source:"Cloverdale's Got Talent 2025 rules and application",Url:"https://cloverdalecitrusfair.org/wp-content/uploads/2025/01/2025-Talent-Show-Form-Bilingual.pdf"}],u={TemplateKey:e,Year:2025,Note:i,Page:a,ParticipantTypes:t,AgeGroups:n,Competitions:o,CompetitionAgeGroups:r,Variables:l,Evidence:s};export{n as AgeGroups,r as CompetitionAgeGroups,o as Competitions,s as Evidence,i as Note,a as Page,t as ParticipantTypes,e as TemplateKey,l as Variables,d as Year,u as default};
